// Detect capabilities, never browser brands (CriOS/FxiOS/EdgiOS UA tokens say nothing about the engine).
export const caps = () => ({
  installPrompt: 'onbeforeinstallprompt' in window,
  push: 'PushManager' in window && 'serviceWorker' in navigator,
  notifications: 'Notification' in window, // undefined in an iOS tab
  vibrate: 'vibrate' in navigator,
  badge: 'setAppBadge' in navigator,
  wakeLock: 'wakeLock' in navigator,
  share: 'share' in navigator,
});
// iPadOS 13+ claims to be a Mac: check touch points too (pure, so it is unit-testable)
export const isIos = (ua: string, touchPoints: number) => /iPad|iPhone|iPod/.test(ua) || (/Macintosh/.test(ua) && touchPoints > 1);

interface BeforeInstallPromptEvent extends Event { prompt(): Promise<void>; readonly userChoice: Promise<{ outcome: 'accepted' | 'dismissed' }> }
const isBip = (e: Event): e is BeforeInstallPromptEvent => 'prompt' in e && typeof e.prompt === 'function' && 'userChoice' in e;
let offer: BeforeInstallPromptEvent | null = null;
addEventListener('beforeinstallprompt', (e) => { if (!isBip(e)) return; e.preventDefault(); offer = e; showInstallButton(); });
addEventListener('appinstalled', () => { offer = null; hideInstallButton(); });
export async function install() { const o = offer; offer = null; if (!o) return false; await o.prompt(); return (await o.userChoice).outcome === 'accepted'; }

// Pure decision: which instructions to show
export type InstallPath = 'installed' | 'prompt' | 'ios-share-sheet' | 'mac-safari-dock' | 'browser-menu';
export const installPath = (s: { installed: boolean; hasPrompt: boolean; ios: boolean; macSafari: boolean }): InstallPath =>
  s.installed ? 'installed' : s.hasPrompt ? 'prompt' : s.ios ? 'ios-share-sheet' : s.macSafari ? 'mac-safari-dock' : 'browser-menu';
// Copy: iOS = Share -> Add to Home Screen; macOS Safari 17+ = File -> Add to Dock; Android Firefox/others = menu -> Add to Home screen / Install

declare global { interface Navigator { readonly standalone?: boolean } } // iOS-only, non-standard
const MODES = ['standalone', 'fullscreen', 'minimal-ui', 'window-controls-overlay'] as const;
export const isInstalledWindow = (mq: (q: string) => boolean = (q) => matchMedia(q).matches, iosStandalone = navigator.standalone === true) =>
  iosStandalone || MODES.some((m) => mq(`(display-mode: ${m})`));
// Desktop users can pop a tab out into an app window and back: listen for changes
for (const m of MODES) matchMedia(`(display-mode: ${m})`).addEventListener('change', refreshInstalledState);

