// Call from a click handler only
export async function enablePush(reg: ServiceWorkerRegistration, key: Uint8Array): Promise<'install-first' | 'denied' | 'ok'> {
  if (!('Notification' in window) || !('PushManager' in window)) return 'install-first'; // iOS tab
  if ((await Notification.requestPermission()) !== 'granted') return 'denied';
  const sub = await reg.pushManager.subscribe({ userVisibleOnly: true, applicationServerKey: key });
  await saveSubscription(sub.toJSON());
  return 'ok';
}
// Optional worker methods differ: guard them (pure, unit-tested)
export const notifiesThroughWorker = (r: { showNotification?: unknown; getNotifications?: unknown }) =>
  typeof r.showNotification === 'function' && typeof r.getNotifications === 'function';

