const PATTERNS = { tap: [8], tick: [14], notice: [12, 60, 12] } as const; // short = taps, not buzzes
export function haptic(kind: keyof typeof PATTERNS, enabled: boolean): boolean {
  if (!enabled || !('vibrate' in navigator) || matchMedia('(prefers-reduced-motion: reduce)').matches) return false;
  return navigator.vibrate([...PATTERNS[kind]]); // false without user activation
}

export async function goFullscreen(el: HTMLElement, video?: HTMLVideoElement) {
  if (document.fullscreenEnabled) return el.requestFullscreen({ navigationUI: 'hide' });
  const native = video && Reflect.get(video, 'webkitEnterFullscreen');
  if (video && typeof native === 'function') native.call(video); // iPhone: native video player
}
