export function onResume(reconnect: (why: 'visible' | 'bfcache' | 'online' | 'resume') => void) {
  document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'visible') reconnect('visible'); });
  addEventListener('pageshow', (e) => { if (e.persisted) reconnect('bfcache'); });
  addEventListener('online', () => reconnect('online'));
  document.addEventListener('resume', () => reconnect('resume')); // Chromium only
}
// Don't trust ws.readyState after a resume: ping and reopen if no pong within ~3s,
// then fetch everything since the last event id. Backoff with jitter on failure.

let lock: WakeLockSentinel | null = null;
export async function keepAwake() {
  if (!('wakeLock' in navigator)) return;
  try { lock = await navigator.wakeLock.request('screen'); } catch { /* hidden page, low battery, policy */ }
}
document.addEventListener('visibilitychange', () => { if (lock?.released && document.visibilityState === 'visible') void keepAwake(); });
export const release = () => lock?.release();

