// service worker
self.addEventListener('notificationclick', (e) => {
  e.notification.close();
  e.waitUntil((async () => {
    const url = new URL(String(e.notification.data?.url ?? '/'), self.registration.scope).href;
    const [win] = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
    if (win) { await win.focus(); win.postMessage({ type: 'open', url }); return; }
    await self.clients.openWindow(url);
  })());
});

export async function getMedia(c: MediaStreamConstraints): Promise<MediaStream> {
  try { return await navigator.mediaDevices.getUserMedia(c); } // only from a tap
  catch (e) {
    if (e instanceof DOMException && e.name === 'NotAllowedError') showHowToAllow(); // Settings path per platform
    throw e;
  }
}
