export function watchClose(close: () => void): () => void {
  if ('CloseWatcher' in window) { const w = new CloseWatcher(); w.addEventListener('close', close); return () => w.destroy(); }
  history.pushState({ sheet: true }, '');                  // fallback: a history entry for the sheet
  const onPop = () => close();
  addEventListener('popstate', onPop, { once: true });
  return () => { removeEventListener('popstate', onPop); if (history.state?.sheet) history.back(); };
}
